package com.lzx.smartmes.production.service;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lzx.smartmes.common.enums.ProductionOrderStatus;import com.lzx.smartmes.common.exception.BusinessException;import com.lzx.smartmes.production.entity.ProductionOrder;import com.lzx.smartmes.production.mapper.ProductionOrderMapper;import com.lzx.smartmes.production.service.impl.ProductionOrderServiceImpl;import org.junit.jupiter.api.Test;import java.math.BigDecimal;
class ProductionOrderServiceTest {@Test void rejectsIllegalStart(){ProductionOrderMapper m=mock(ProductionOrderMapper.class);ProductionOrder o=new ProductionOrder();o.setStatus(ProductionOrderStatus.PLANNED);when(m.selectById(1L)).thenReturn(o);assertThrows(BusinessException.class,()->new ProductionOrderServiceImpl(m).start(1L));}@Test void startsReleasedOrder(){ProductionOrderMapper m=mock(ProductionOrderMapper.class);ProductionOrder o=new ProductionOrder();o.setStatus(ProductionOrderStatus.RELEASED);o.setPlanQuantity(BigDecimal.ONE);o.setCompletedQuantity(BigDecimal.ZERO);when(m.selectById(1L)).thenReturn(o);when(m.updateById(o)).thenReturn(1);assertEquals(ProductionOrderStatus.RUNNING,new ProductionOrderServiceImpl(m).start(1L).getStatus());}}
